// Generated by Tools/GameData/dungeons.py from the source game's game.db and maps/*.map: the dungeons entered from
// the start region (and from inside them), their plans, monsters, containers and entry rules, the bosses' loot,
// the keys and treasures, and the outdoor monsters that drop keys. Do not edit by hand.
using System.Collections.Generic;
using UnityEngine;

namespace RPG.EditorTools
{
    internal static class DungeonData
    {
        internal sealed class Dungeon
        {
            /// <summary>Asset name.</summary>
            public string Id;
            public string Name;
            /// <summary>The source game's map file.</summary>
            public string Map;
            public int MinLevel;
            public int MaxPlayers;
            /// <summary>The key one player uses up to open it (an id in <see cref="Items"/>), or null.</summary>
            public string Key;
            /// <summary>Where its entrance stands in the world (when <see cref="Parent"/> is null).</summary>
            public Vector3Int WorldEntrance;
            /// <summary>The source game has the entrance further south than this world reaches: it stands at the edge.</summary>
            public bool MovedToEdge;
            /// <summary>The dungeon whose plan holds the entrance (null: the world), and the entrance's cell there.</summary>
            public string Parent;
            public Vector3Int ParentCell;
            /// <summary>Where players arrive.</summary>
            public Vector3Int Arrival;
            /// <summary>The plan, row y = index, column x: '.' walkable, '#' not.</summary>
            public string[] Rows;
            /// <summary>Portals out: cell, the world cell they lead to, name.</summary>
            public (Vector3Int cell, Vector3Int world, string name)[] Exits;
            /// <summary>
            /// Monsters: cell, name, level, elite (the source game's elites and boss-flagged monsters), boss (with a loot table),
            /// health as a multiple of a normal monster of its level (0: the usual), damage as a multiple of a normal
            /// monster's (0: the usual), gold multiple, loot table (0: none), chances of a blue, gold and purple piece.
            /// </summary>
            public (Vector3Int cell, string name, int level, bool elite, bool boss, float health, float damage, float gold, int loot,
                float blue, float goldQuality, float purple)[] Monsters;
            /// <summary>Containers: cell, kind (0 crate or barrel, 1 chest, 2 strongbox), level, name.</summary>
            public (Vector3Int cell, int kind, int level, string name)[] Chests;
        }

